content.query:
let g = ClaudeCost(datetime({TimeRange:startISO}), datetime({TimeRange:endISO}))
| summarize unpriced = round(sumif(usd, not(priced_ok)), 2), nodev = round(sumif(usd, actor == 'unattributed'), 2), nounit = round(sumif(usd, business_unit == 'unassigned'), 2), moved = round(sumif(usd, attribution == 'moved'), 2);
g | project Metric = 'Spend on unpriced models (USD)', Value = unpriced
| union (g | project Metric = 'Spend with no developer (USD)', Value = nodev)
| union (g | project Metric = 'Spend with no business unit (USD)', Value = nounit)
| union (g | project Metric = 'Spend that moved unit (USD)', Value = moved)
